func inputsFingerprint(shards []inputShardInfo) string {
        if len(shards) == 0 {
                return emptySHA256
        }
        var concat []byte
        for _, s := range shards {
                concat = append(concat, []byte(s.SHA256)...)
        }
        return sha256Hex(concat)
}

func argvSHA256(argv []string) string {
        var parts []string
        for _, tok := range argv {
                if !strings.Contains(tok, "/") {
                        parts = append(parts, tok)
                }
        }
        joined := strings.Join(parts, " ")
        return sha256Hex([]byte(joined))
}
